/**
 * 依頼の対象
 * 依頼が指すもの。描画ノードの ID は保存しない。
 * @see model/target.dt:21
 */
export type ModelTarget =
    /**
     * ワークスペース
     * ワークスペース全体。
     */
    | {
          readonly kind: 'Workspace';
          /** ソースの言語 */
          readonly scope?: SourceLanguage;
      }
    /**
     * モデルの要素
     * `.dt` モデルの要素。
     */
    | {
          readonly kind: 'DtElement';
          /** 要素名 */
          readonly element: ElementName;
      }
    /**
     * ストーミングの要素
     * `.dtes` ストーミングの要素（統合キャンバスでイベントを選ぶと、イベントの定義を指す）。
     */
    | {
          readonly kind: 'DtesElement';
          /** ストーミング名 */
          readonly storming: StormingName;
          /** ストーミング内の要素名 */
          readonly local: StormingLocalName;
      }
    /**
     * イベントの出現
     * タイムラインでのイベントの出現。タイムラインのビューからだけ指せる。
     */
    | {
          readonly kind: 'DtesOccurrence';
          /** ストーミング名 */
          readonly storming: StormingName;
          /** タイムライン名 */
          readonly timeline: TimelineName;
          /** ストーミングのイベント名 */
          readonly eventName: StormingEventName;
          /** 出現の道筋 */
          readonly occurrence: OccurrencePath;
      };

/**
 * Whether two ModelTarget values are equal: by `kind` and the fields of the variant (ADR 0016).
 * @see model/target.dt:21
 */
export function equalModelTarget(a: ModelTarget, b: ModelTarget): boolean {
    if (a.kind !== b.kind) return false;
    if (a.kind === 'Workspace') {
        const y = b as Extract<ModelTarget, { readonly kind: 'Workspace' }>;
        return sameOptional(a.scope, y.scope, ($16: string, $17: string) => $16 === $17);
    }
    if (a.kind === 'DtElement') {
        const y = b as Extract<ModelTarget, { readonly kind: 'DtElement' }>;
        return a.element === y.element;
    }
    if (a.kind === 'DtesElement') {
        const y = b as Extract<ModelTarget, { readonly kind: 'DtesElement' }>;
        return a.storming === y.storming && a.local === y.local;
    }
    if (a.kind === 'DtesOccurrence') {
        const y = b as Extract<ModelTarget, { readonly kind: 'DtesOccurrence' }>;
        return a.storming === y.storming && a.timeline === y.timeline && a.eventName === y.eventName && a.occurrence === y.occurrence;
    }
    return true;
}

/**
 * ソースの範囲
 * ソースの範囲（両端を含む）。
 * @invariant ordered (開始が終了より前): startLine < endLine or (startLine == endLine and startColumn <= endColumn)
 * @see model/target.dt:45
 */
export interface SourceRange {
    /** ワークスペース内パス */
    readonly path: WorkspacePath;
    /** 開始行 */
    readonly startLine: LineNumber;
    /** 開始列 */
    readonly startColumn: ColumnNumber;
    /** 終了行 */
    readonly endLine: LineNumber;
    /** 終了列 */
    readonly endColumn: ColumnNumber;
}

/**
 * Whether two SourceRange values are equal: by all their fields (ADR 0016).
 * @see model/target.dt:45
 */
export function equalSourceRange(a: SourceRange, b: SourceRange): boolean {
    return a.path === b.path && a.startLine === b.startLine && a.startColumn === b.startColumn && a.endLine === b.endLine && a.endColumn === b.endColumn;
}

/**
 * The invariants of SourceRange that a value violates, in declaration order; empty when it holds them all.
 * @see model/target.dt:45
 */
export function checkSourceRange(sourceRange: SourceRange): readonly 'ordered'[] {
    const violated: 'ordered'[] = [];
    if (!((sourceRange.startLine < sourceRange.endLine) || ((sourceRange.startLine === sourceRange.endLine) && (sourceRange.startColumn <= sourceRange.endColumn)))) violated.push('ordered');
    return violated;
}

/**
 * 依頼時の対象
 * 依頼を作ったときの対象。対象の道筋がもう合わなくなっても付け替えず、古くなったと示す。
 * @invariant workspaceHasNoRange (ワークスペース全体には範囲がない): target.kind == ModelTarget.Workspace implies not exists(range)
 * @see model/target.dt:56
 */
export interface TargetSnapshot {
    /** 依頼の対象 */
    readonly target: ModelTarget;
    /** 依頼時のリビジョン */
    readonly sourceRevision: RevisionId;
    /** 依頼時の表示名 */
    readonly label?: string;
    /** 依頼時の範囲 */
    readonly range?: SourceRange;
}

/**
 * Whether two TargetSnapshot values are equal: by all their fields (ADR 0016).
 * @see model/target.dt:56
 */
export function equalTargetSnapshot(a: TargetSnapshot, b: TargetSnapshot): boolean {
    return equalModelTarget(a.target, b.target) && a.sourceRevision === b.sourceRevision && sameOptional(a.label, b.label, ($18: string, $19: string) => $18 === $19) && sameOptional(a.range, b.range, equalSourceRange);
}

/**
 * The invariants of TargetSnapshot that a value violates, in declaration order; empty when it holds them all.
 * @see model/target.dt:56
 */
export function checkTargetSnapshot(targetSnapshot: TargetSnapshot): readonly 'workspaceHasNoRange'[] {
    const violated: 'workspaceHasNoRange'[] = [];
    if (!(!(targetSnapshot.target.kind === "Workspace") || !(targetSnapshot.range !== undefined))) violated.push('workspaceHasNoRange');
    return violated;
}

/** Events of Collaboration that are persisted (declared `persistent`). */
export type PersistentEvent = RunQueued | RunStarted | RunCompleted | RunNeedsClarification | RunDeclined | RunFailed | RunCancelled | MarkPlaced | MarkRemoved | RequestSent | RequestDismissed | RevisionRecorded | RevisionRestored | RevisionConfirmed | SessionStarted | ParticipantJoined | SessionClosed;

/** Events of Collaboration. */
export type DomainEvent = RunQueued | RunStarted | RunCompleted | RunNeedsClarification | RunDeclined | RunFailed | RunCancelled | MarkPlaced | MarkRemoved | RequestSent | RequestDismissed | RevisionRecorded | RevisionRestored | RevisionConfirmed | SessionStarted | ParticipantJoined | SessionClosed;

/** Aggregates of Collaboration. */
export type Aggregate = AgentRun | Mark | Request | Revision | Session;
